<section class="finance-section-heading"><div><span class="finance-kicker">Payment support</span><h2 class="h4 mb-1">Refunds</h2><p class="finance-muted mb-0">Submit a request for a paid transaction. System Admin reviews it; a refund is complete only after the provider confirms it.</p></div></section>
<?php if($refundableOrders): ?><section class="finance-panel mb-3"><h3 class="h5 mb-3">Request a refund</h3><?php $formStart('refund-request'); ?><div class="finance-form-grid">
<label class="finance-form-field finance-form-wide"><span>Paid transaction</span><select class="form-select" name="order_id" required><option value="">Choose a payment</option><?php foreach($refundableOrders as $item): ?><option value="<?= (int)$item['id'] ?>"><?= $esc($item['reference'].' · '.$item['item_name']) ?> · <?= $money($item['amount']) ?></option><?php endforeach ?></select></label>
<label class="finance-form-field"><span>Amount to request (₱)</span><input class="form-control" name="amount" inputmode="decimal" placeholder="0.00" required></label>
<label class="finance-form-field finance-form-wide"><span>Reason</span><textarea class="form-control" name="reason" rows="2" maxlength="255" placeholder="Briefly explain the request" required></textarea></label>
</div><div class="finance-form-actions"><button class="btn btn-primary" type="submit">Submit refund request</button></div></form></section>
<?php elseif(!$admin): ?><div class="finance-status-callout mb-3">You have no paid transactions available for a new refund request.</div><?php endif ?>
<?php if(!$refunds): ?><section class="finance-empty-state"><div class="finance-empty-icon"><i class="ph-bold ph-arrow-u-up-left" aria-hidden="true"></i></div><div><h3 class="h5 mb-1">No refund requests yet</h3><p class="finance-muted mb-0">Submitted requests and provider-confirmed refunds will appear here.</p></div></section>
<?php else: ?><section class="finance-panel"><h3 class="h5 mb-3">Refund history</h3><div class="finance-record-list"><?php foreach($refunds as $r): ?><article class="finance-record finance-refund-record"><div><strong><?= $money($r['amount']) ?></strong><span class="finance-state <?= $r['status']==='CONFIRMED'?'good':($r['status']==='REJECTED'?'bad':'wait') ?> ms-2"><?= $esc(ucwords(strtolower(str_replace('_',' ',(string)$r['status'])))) ?></span><span class="finance-muted small d-block mt-1"><?= $esc($r['reason']) ?></span><?php if($admin): ?><span class="finance-muted small d-block">Provider: <?= $esc($r['provider_status']??'Not submitted') ?> · Accounting: <?= $esc($r['accounting_status']) ?></span><?php endif ?></div>
<?php if($admin): ?><div class="finance-refund-actions">
<?php if($r['status']==='REQUESTED'): $formStart('refund-review'); ?><input type="hidden" name="refund_id" value="<?= (int)$r['id'] ?>"><label class="finance-form-field"><span>Decision note</span><input class="form-control" name="note" maxlength="255" required></label><div class="finance-form-actions"><button name="decision" value="approve" class="btn btn-primary btn-sm">Approve request</button><button name="decision" value="reject" class="btn btn-outline-danger btn-sm">Reject request</button></div></form><?php endif ?>
<?php if($r['status']==='APPROVED'): $formStart('refund-submit'); ?><input type="hidden" name="refund_id" value="<?= (int)$r['id'] ?>"><button class="btn btn-primary btn-sm">Submit approved refund to PayMongo</button></form><?php endif ?>
<?php if($r['provider_id']): $formStart('refund-reconcile'); ?><input type="hidden" name="refund_id" value="<?= (int)$r['id'] ?>"><button class="btn btn-outline-primary btn-sm">Check provider status</button></form><?php elseif(in_array($r['status'],['UNCERTAIN','SUBMITTING'],true)): $formStart('attach-refund'); ?><input type="hidden" name="refund_id" value="<?= (int)$r['id'] ?>"><label class="finance-form-field"><span>Recovered PayMongo refund reference</span><input class="form-control" name="provider_id" placeholder="ref_…" required></label><button class="btn btn-outline-primary btn-sm">Verify and attach refund</button></form><?php endif ?>
</div><?php endif ?></article><?php endforeach ?></div></section><?php endif ?>
